import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Random;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public long nextLong() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return Long.MIN_VALUE;
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            long res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return negative ? -res : res;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static class Node {
        long key;
        int priority;
        int count;
        int size;
        Node left, right;

        Node(long key, int priority) {
            this.key = key;
            this.priority = priority;
            this.count = 1;
            this.size = 1;
        }
    }

    static final Random rng = new Random();

    static int getSize(Node t) {
        return t == null ? 0 : t.size;
    }

    static void update(Node t) {
        if (t != null) {
            t.size = t.count + getSize(t.left) + getSize(t.right);
        }
    }

    static Node rotateRight(Node y) {
        Node x = y.left;
        y.left = x.right;
        x.right = y;
        update(y);
        update(x);
        return x;
    }

    static Node rotateLeft(Node x) {
        Node y = x.right;
        x.right = y.left;
        y.left = x;
        update(x);
        update(y);
        return y;
    }

    static Node insert(Node t, long key) {
        if (t == null) {
            return new Node(key, rng.nextInt());
        }
        if (key == t.key) {
            t.count++;
            t.size++;
            return t;
        } else if (key < t.key) {
            t.left = insert(t.left, key);
            if (t.left.priority > t.priority) {
                t = rotateRight(t);
            }
        } else {
            t.right = insert(t.right, key);
            if (t.right.priority > t.priority) {
                t = rotateLeft(t);
            }
        }
        update(t);
        return t;
    }

    static int countLessOrEqual(Node t, long key) {
        if (t == null) return 0;
        if (key < t.key) {
            return countLessOrEqual(t.left, key);
        } else if (key == t.key) {
            return getSize(t.left) + t.count;
        } else {
            return getSize(t.left) + t.count + countLessOrEqual(t.right, key);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        if (n <= 0) {
            out.flush();
            return;
        }

        Node root = null;
        long lastPenalty = 0;

        for (int k = 1; k <= n; k++) {
            long x = scanner.nextLong();
            long y = scanner.nextLong();

            long realX = x + lastPenalty;
            long realY = y + lastPenalty;
            long distSq = realX * realX + realY * realY;

            int currentPenalty = countLessOrEqual(root, distSq);
            out.println(currentPenalty);

            root = insert(root, distSq);
            lastPenalty = currentPenalty;
        }

        out.flush();
    }
}
